// Lighting stage only sets up clustered lighting data
// It doesn't read/write main color targets - just prepares lighting for GeometryStage
⋮----
// Transparency reads SceneColor, writes to SceneColorFinal
⋮----
// Skybox reads from current scene color, writes additively to same target
⋮----
stage->setOutput(sceneTarget);  // Write back to same target (additive)
