lightingStage->setLightingShader(lightingShader);      // Use dedicated lighting shader
lightingStage->setLightManager(lightManagerPtr);       // Set the light manager
lightingStage->setShadowMappingEnabled(true);          // Enable shadows
// Set ambient lighting for isometric 3D depth perception
lightingStage->setAmbientLight(glm::vec3(0.3f, 0.3f, 0.4f)); // Soft bluish ambient
